#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdio>
using namespace std;

using ll = long long;
using VI = vector<int>;

const ll MOD = 1000000007LL;
const ll MOD2 = 998244353LL;

VI pos[10];
int cnt = 0;
ll pw[15];
ll s[15];
ll cnt2, n;
int ans = 0;

int query(int fixpre, ll val) {
    ll res = 0;
    for (int d = 0; d < 7; ++d) {
        ll offset = (val - (ll)fixpre * pw[d]) % MOD2;
        if (offset < 0) offset += MOD2;
        int p = (int)(lower_bound(pos[d].begin(), pos[d].end(), MOD2 - offset) - pos[d].begin());
        res = (res + s[d] + offset * (ll)pos[d].size() - MOD2 * (ll)((int)pos[d].size() - p)) % MOD;
    }
    return (int)res;
}

void build_positions() {
    ll pow10[8];
    pow10[0] = 1;
    for (int i = 1; i <= 7; ++i) pow10[i] = pow10[i - 1] * 10;

    ll subtree[8];
    for (int i = 0; i < 7; ++i) subtree[i] = (pow10[7 - i] - 1) / 9;

    for (int d = 0; d < 7; ++d) {
        int limit = (int)pow10[d];
        for (int val = 0; val < limit; ++val) {
            ll idx = d;
            int tmp = val;
            for (int k = d; k >= 1; --k) {
                int digit = tmp % 10;
                tmp /= 10;
                idx += digit * subtree[k];
            }
            int x = (int)((idx - val + MOD2) % MOD2);
            pos[d].push_back(x);
            s[d] += x;
        }
    }

    cnt = 0;
    for (int i = 0; i < 7; ++i) {
        sort(pos[i].begin(), pos[i].end());
        cnt += (int)pos[i].size();
    }
}

void dfs2(ll val) {
    if (val * 1000000LL + 999999LL <= n && val * 10000000LL > n) {
        ans = (ans + query(val, cnt2 + 1)) % MOD;
        cnt2 += cnt;
    } else {
        ++cnt2;
        ans = (ans + ((cnt2 - val) % MOD2 + MOD2) % MOD2) % MOD;
        for (int i = (val == 0 ? 1 : 0); i < 10; ++i) {
            if (val * 10 + i <= n) dfs2(val * 10 + i);
        }
    }
}

int main() {
    build_positions();
    pw[0] = 1;
    for (int i = 1; i < 13; ++i) pw[i] = pw[i - 1] * 10;
    scanf("%lld", &n);
    cnt2 = -1;
    dfs2(0);
    printf("%d\n", ans);
    return 0;
}
