import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007L;
    static final long MOD2 = 998244353L;

    static List<Integer>[] pos = new List[10];
    static long[] s = new long[15];
    static long[] pw = new long[13];
    static long cnt2, n;
    static int ans = 0;

    static int query(int fixpre, long val) {
        long res = 0;
        for (int d = 0; d < 7; ++d) {
            long offset = (val - (long)fixpre * pw[d]) % MOD2;
            if (offset < 0) offset += MOD2;
            int target = (int)(MOD2 - offset);
            int p = Collections.binarySearch(pos[d], target);
            if (p < 0) p = -p - 1;
            res = (res + s[d] + offset * pos[d].size() - MOD2 * (pos[d].size() - p)) % MOD;
        }
        return (int)res;
    }

    static void buildPositions() {
        long[] pow10 = new long[8];
        pow10[0] = 1;
        for (int i = 1; i <= 7; ++i) pow10[i] = pow10[i - 1] * 10;

        long[] subtree = new long[8];
        for (int i = 0; i < 7; ++i) subtree[i] = (pow10[7 - i] - 1) / 9;

        for (int d = 0; d < 7; ++d) {
            int limit = (int)pow10[d];
            for (int val = 0; val < limit; ++val) {
                long idx = d;
                int tmp = val;
                for (int k = d; k >= 1; --k) {
                    int digit = tmp % 10;
                    tmp /= 10;
                    idx += digit * subtree[k];
                }
                int x = (int)((idx - val + MOD2) % MOD2);
                pos[d].add(x);
                s[d] += x;
            }
        }

        for (int i = 0; i < 7; ++i) {
            Collections.sort(pos[i]);
        }
    }

    static void dfs2(long val) {
        if (val * 1000000L + 999999L <= n && val * 10000000L > n) {
            ans = (ans + query((int)val, cnt2 + 1)) % (int)MOD;
            cnt2 += pos[0].size() + pos[1].size() + pos[2].size() + pos[3].size() + pos[4].size() + pos[5].size() + pos[6].size();
        } else {
            ++cnt2;
            long diff = (cnt2 - val) % MOD2;
            if (diff < 0) diff += MOD2;
            ans = (int)((ans + diff) % MOD);
            int start = (val == 0 ? 1 : 0);
            for (int i = start; i < 10; ++i) {
                long next = val * 10 + i;
                if (next <= n) dfs2(next);
            }
        }
    }

    public static void main(String[] args) {
        for (int i = 0; i < 10; ++i) pos[i] = new ArrayList<>();
        pw[0] = 1;
        for (int i = 1; i < 13; ++i) pw[i] = pw[i - 1] * 10;

        buildPositions();

        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        cnt2 = -1;
        dfs2(0);
        System.out.println(ans);
    }
}
